67			if (!this._editor.getOption(EditorOption.formatOnType)) {
68				return;
69			}
70	
71			// no model
72			if (!this._editor.hasModel()) {
73				return;
74			}
75	
76			const model = this._editor.getModel();
77	
78			// no support
79			const [support] = this._languageFeaturesService.onTypeFormattingEditProvider.ordered(model);
80			if (!support || !support.autoFormatTriggerCharacters) {
81				return;
82			}
83	
84			// register typing listeners that will trigger the format
85			const triggerChars = new CharacterSet();
86			for (const ch of support.autoFormatTriggerCharacters) {
87				triggerChars.add(ch.charCodeAt(0));
88			}
89			this._sessionDisposables.add(this._editor.onDidType((text: string) => {
90				const lastCharCode = text.charCodeAt(text.length - 1);
91				if (triggerChars.has(lastCharCode)) {
92					this._trigger(String.fromCharCode(lastCharCode));
93				}
94			}));
95		}
96	
97		private _trigger(ch: string): void {
98			if (!this._editor.hasModel()) {
99				return;
100			}
101	
102			if (this._editor.getSelections().length > 1 || !this._editor.getSelection().isEmpty()) {
103				return;
104			}
105	
106			const model = this._editor.getModel();
107			const position = this._editor.getPosition();
108			const cts = new CancellationTokenSource();
109	
110			// install a listener that checks if edits happens before the
111			// position on which we format right now. If so, we won't
112			// apply the format edits
113			const unbind = this._editor.onDidChangeModelContent((e) => {
114				if (e.isFlush) {
115					// a model.setValue() was called
116					// cancel only once
117					cts.cancel();
118					unbind.dispose();
119					return;
120				}
121	
122				for (let i = 0, len = e.changes.length; i < len; i++) {
123					const change = e.changes[i];
124					if (change.range.endLineNumber <= position.lineNumber) {
125						// cancel only once
126						cts.cancel();
127						unbind.dispose();
128						return;
129					}
130				}
131			});
132	
133			getOnTypeFormattingEdits(
134				this._workerService,
135				this._languageFeaturesService,
136				model,
137				position,
138				ch,
139				model.getFormattingOptions(),
140				cts.token
141			).then(edits => {
142				if (cts.token.isCancellationRequested) {
143					return;
144				}
145				if (isNonEmptyArray(edits)) {
146					this._accessibilitySignalService.playSignal(AccessibilitySignal.format, { userGesture: false });
147					FormattingEdit.execute(this._editor, edits, true);
148				}
149			}).finally(() => {
150				unbind.dispose();
151			});
152		}
153	}
154	
155	class FormatOnPaste implements IEditorContribution {
156	
157		public static readonly ID = 'editor.contrib.formatOnPaste';
158	
159		private readonly _callOnDispose = new DisposableStore();
160		private readonly _callOnModel = new DisposableStore();
161	
162		constructor(
163			private readonly editor: ICodeEditor,
164			@ILanguageFeaturesService private readonly _languageFeaturesService: ILanguageFeaturesService,
165			@IInstantiationService private readonly _instantiationService: IInstantiationService,
166		) {
167			this._callOnDispose.add(editor.onDidChangeConfiguration(() => this._update()));
168			this._callOnDispose.add(editor.onDidChangeModel(() => this._update()));
169			this._callOnDispose.add(editor.onDidChangeModelLanguage(() => this._update()));
170			this._callOnDispose.add(_languageFeaturesService.documentRangeFormattingEditProvider.onDidChange(this._update, this));
171		}
172	
173		dispose(): void {
174			this._callOnDispose.dispose();
175			this._callOnModel.dispose();
176		}
